insert into public.diretorio_salas (nome,num,nome_en,nome_pt,descricao_en,descricao_pt,raridade_en,raridade_pt,custo_en,custo_pt,tipo_en,tipo_pt,categorias,diretorio,imagem,fonte,atualizado_em) values
('Weight Room',85,'Weight Room','Weight Room','An exercise room outfitted with weightlifting equipment. A good workout session here will wipe you out and leave you with little energy left for exploring.','Uma sala de exercícios equipada com aparelhos de musculação. Uma boa sessão de treino aqui vai lhe esgotar e deixar pouca energia para explorar.','Rare','Raro','None (no gem cost)','Nenhum (sem custo em gemas)','Red Room','Sala Vermelha (Red Room)',ARRAY['Red Room']::text[],'Red Rooms','https://gppfzdlqauygzvpodbdh.supabase.co/storage/v1/object/public/salas/Red%20Rooms/Weight%20Room.png','https://blueprince.wiki.gg/wiki/Weight_Room',now()),
('Furnace',86,'Furnace','Furnace','The main centralized heat source for the estate. You may find yourself starting to sweat after drafting this room.','A principal fonte centralizada de calor da propriedade. Você pode acabar começando a suar depois de sortear este cômodo.','Rare','Raro','None (no gem cost)','Nenhum (sem custo em gemas)','Red Room, Dead End','Sala Vermelha (Red Room), Beco sem saída (Dead End)',ARRAY['Red Room']::text[],'Red Rooms','https://gppfzdlqauygzvpodbdh.supabase.co/storage/v1/object/public/salas/Red%20Rooms/Furnace.png','https://blueprince.wiki.gg/wiki/Furnace',now()),
('Dovecote',87,'Dovecote','Dovecote','A towering loft serving home to many of the feathered locals of Mount Holly. As a devout bird-watcher and amateur ornithologist Mary had petitioned her uncle for years for this to be built on the estate.','Um pombal imponente que serve de lar para muitos dos moradores emplumados de Mount Holly. Como devota observadora de pássaros e ornitóloga amadora, Mary passou anos pedindo ao tio que este fosse construído na propriedade.','Unusual','Incomum','None (no gem cost)','Nenhum (sem custo em gemas)','Blueprint, Addition','Blueprint (planta azul), Adição (Addition)',ARRAY['Studio Addition']::text[],'Studio Additions','https://gppfzdlqauygzvpodbdh.supabase.co/storage/v1/object/public/salas/Studio%20Additions/Dovecote.png','https://blueprince.wiki.gg/wiki/Dovecote',now()),
('The Kennel',88,'The Kennel','The Kennel','Home to several of Sinclair''s hunting companions. It can be assumed these friendly hounds have been anxious to meet their new master.','Lar de vários dos companheiros de caça de Sinclair. Pode-se presumir que estes amigáveis cães de caça estejam ansiosos para conhecer seu novo dono.','Standard','Padrão','None (no gem cost)','Nenhum (sem custo em gemas)','Blueprint, Addition','Blueprint (planta azul), Adição (Addition)',ARRAY['Studio Addition']::text[],'Studio Additions','https://gppfzdlqauygzvpodbdh.supabase.co/storage/v1/object/public/salas/Studio%20Additions/The%20Kennel.png','https://blueprince.wiki.gg/wiki/The_Kennel',now()),
('Clock Tower',89,'Clock Tower','Clock Tower','Access to Mt. Holly''s Clock Tower has always been heavily restricted. Which might explain why maintenance has been unable to mend the perpetually halted clock face, a testament to the unchanging winds of the sacred hour.','O acesso à Torre do Relógio de Mt. Holly sempre foi fortemente restrito. O que talvez explique por que a manutenção não conseguiu consertar o mostrador perpetuamente parado, um testemunho dos ventos imutáveis da hora sagrada.','unusual','Incomum','1 gem','1 gema','Tomorrow, Blueprint, Dead End, Addition','Tomorrow, Blueprint (planta azul), Beco sem saída (Dead End), Adição (Addition)',ARRAY['Studio Addition']::text[],'Studio Additions','https://gppfzdlqauygzvpodbdh.supabase.co/storage/v1/object/public/salas/Studio%20Additions/Clock%20Tower.png','https://blueprince.wiki.gg/wiki/Clock_Tower',now()),
('Classroom',90,'Classroom','Classroom','An exact copy of the floorplan used in the architectural design of Reddington Elementary. These copies were deployed in Mt. Holly as a short term solution, to allow the curriculum to continue uninterrupted while the new school was being built in town.','Uma cópia exata da planta usada no projeto arquitetônico da Escola Primária de Reddington. Estas cópias foram implantadas em Mt. Holly como solução de curto prazo, para permitir que o currículo continuasse sem interrupção enquanto a nova escola era construída na cidade.','Unusual','Incomum','1 gem','1 gema','Drafting, Blueprint, Addition','Sorteio (Drafting), Blueprint (planta azul), Adição (Addition)',ARRAY['Studio Addition']::text[],'Studio Additions','https://gppfzdlqauygzvpodbdh.supabase.co/storage/v1/object/public/salas/Studio%20Additions/Classroom.png','https://blueprince.wiki.gg/wiki/Classroom',now()),
('Solarium',91,'Solarium','Solarium','A quaint floral sitting room surrounded entirely by tinted glass panes. The Solarium is ideal for tea in the afternoons or getting some sun without the hassle of going outside.','Uma charmosa sala de estar floral totalmente cercada por vidraças fumê. O Solário é ideal para o chá da tarde ou para tomar um pouco de sol sem o transtorno de sair de casa.','Standard','Padrão','1 gem','1 gema','Green Room, Dead End, Addition','Sala Verde (Green Room), Beco sem saída (Dead End), Adição (Addition)',ARRAY['Studio Addition']::text[],'Studio Additions','https://gppfzdlqauygzvpodbdh.supabase.co/storage/v1/object/public/salas/Studio%20Additions/Solarium.png','https://blueprince.wiki.gg/wiki/Solarium',now()),
('Dormitory',92,'Dormitory','Dormitory','These small sleeping quarters, devoid of frills and distractions, are ideal for the student, scholar or denizen of academia who wishes to focus on their studies without diversion or interruption. Study and sleep. Rinse and repeat.','Estes pequenos aposentos, desprovidos de frivolidades e distrações, são ideais para o estudante, o acadêmico ou o habitante da vida universitária que deseja se concentrar nos estudos sem desvios ou interrupções. Estudar e dormir. Repetir tudo de novo.','Standard','Padrão','None (no gem cost)','Nenhum (sem custo em gemas)','Entry, Bedroom, Dead End, Addition','Entrada (Entry), Quarto (Bedroom), Beco sem saída (Dead End), Adição (Addition)',ARRAY['Studio Addition']::text[],'Studio Additions','https://gppfzdlqauygzvpodbdh.supabase.co/storage/v1/object/public/salas/Studio%20Additions/Dormitory.png','https://blueprince.wiki.gg/wiki/Dormitory',now()),
('Vestibule',93,'Vestibule','Vestibule','An ornately framed yet modestly sized hall. It had served as the original antechamber in the old days before eventually being removed from the estate for having doors that were prone to becoming stuck.','Um saguão de moldura ornamentada, porém de tamanho modesto. Serviu de antecâmara original nos velhos tempos, antes de acabar sendo removido da propriedade por ter portas propensas a emperrar.','Unusual','Incomum','2 gems','2 gemas','Entry, Hallway, Addition','Entrada (Entry), Corredor (Hallway), Adição (Addition)',ARRAY['Studio Addition']::text[],'Studio Additions','https://gppfzdlqauygzvpodbdh.supabase.co/storage/v1/object/public/salas/Studio%20Additions/Vestibule.png','https://blueprince.wiki.gg/wiki/Vestibule',now()),
('Casino',94,'Casino','Casino','The Mount Holly Casino offers an intimate and exciting setting for wagers of any scale, and guests may be surprised to discover how much strategy is involved in these machines, which are traditionally only thought of as games of chances. A buy-in of two gems is required for admittance into this exclusive room.','O Cassino de Mount Holly oferece um ambiente íntimo e emocionante para apostas de qualquer escala, e os hóspedes podem se surpreender ao descobrir quanta estratégia está envolvida nestas máquinas, tradicionalmente vistas apenas como jogos de azar. É exigida uma entrada de duas gemas para admissão neste cômodo exclusivo.','Unusual','Incomum','2 gems','2 gemas','Shop, Addition','Loja (Shop), Adição (Addition)',ARRAY['Studio Addition']::text[],'Studio Additions','https://gppfzdlqauygzvpodbdh.supabase.co/storage/v1/object/public/salas/Studio%20Additions/Casino.png','https://blueprince.wiki.gg/wiki/Casino',now()),
('Planetarium',95,'Planetarium','Planetarium','A circular theater featuring a dome shaped projection screen upon which scenes of the stars and galaxies allow viewers to experience the splendor of the heavens.','Um teatro circular com uma tela de projeção em formato de cúpula, na qual cenas das estrelas e galáxias permitem aos espectadores vivenciar o esplendor dos céus.','Standard','Padrão','None (no gem cost)','Nenhum (sem custo em gemas)','Tomorrow, Blueprint, Dead End, Addition','Tomorrow, Blueprint (planta azul), Beco sem saída (Dead End), Adição (Addition)',ARRAY['Found Floorplan']::text[],'Found Floorplans','https://gppfzdlqauygzvpodbdh.supabase.co/storage/v1/object/public/salas/Found%20Floorplans/Planetarium.png','https://blueprince.wiki.gg/wiki/Planetarium',now()),
('Mechanarium',96,'Mechanarium','Mechanarium','An iron vaulted mechanical chamber affixed with motorized panels that can reveal up to 8 different doors depending on the parameters at the time of creation.','Uma câmara mecânica abobadada de ferro, provida de painéis motorizados que podem revelar até 8 portas diferentes, dependendo dos parâmetros no momento de sua criação.','Unusual','Incomum','None (no gem cost)','Nenhum (sem custo em gemas)','Mechanical, Blueprint, Addition','Mecânico (Mechanical), Blueprint (planta azul), Adição (Addition)',ARRAY['Found Floorplan']::text[],'Found Floorplans','https://gppfzdlqauygzvpodbdh.supabase.co/storage/v1/object/public/salas/Found%20Floorplans/Mechanarium.png','https://blueprince.wiki.gg/wiki/Mechanarium',now()),
('Treasure Trove',97,'Treasure Trove','Treasure Trove','Turns out the oft rumored "Treasure of Mount Holly" was more than just a rumor.','Acontece que o tão rumorejado "Tesouro de Mount Holly" era mais do que apenas um boato.','Unusual','Incomum','1 gem','1 gema','Blackprint, Addition','Blackprint (planta negra), Adição (Addition)',ARRAY['Found Floorplan']::text[],'Found Floorplans','https://gppfzdlqauygzvpodbdh.supabase.co/storage/v1/object/public/salas/Found%20Floorplans/Treasure%20Trove.png','https://blueprince.wiki.gg/wiki/Treasure_Trove',now()),
('Throne Room',98,'Throne Room','Throne Room','The former seat of power of Orinda Aries before the current era and the rise of the red banner.','O antigo assento de poder de Orinda Aries antes da era atual e da ascensão do estandarte vermelho.','Rare','Raro','5 gems','5 gemas','Blackprint, Addition','Blackprint (planta negra), Adição (Addition)',ARRAY['Found Floorplan']::text[],'Found Floorplans','https://gppfzdlqauygzvpodbdh.supabase.co/storage/v1/object/public/salas/Found%20Floorplans/Throne%20Room.png','https://blueprince.wiki.gg/wiki/Throne_Room',now()),
('Tunnel',99,'Tunnel','Tunnel','Going under all obstacles, the tunnel pierces through walls and rooms alike. This crudely excavated passage looks to be the work of someone determined to get where they are going regardless of whether the house''s floor plan is accommodating or not.','Passando por baixo de todos os obstáculos, o túnel atravessa paredes e cômodos por igual. Esta passagem toscamente escavada parece ser obra de alguém determinado a chegar aonde quer, independentemente de a planta da casa ser acomodadora ou não.','Standard','Padrão','None (no gem cost)','Nenhum (sem custo em gemas)','Drafting, Hallway, Addition','Sorteio (Drafting), Corredor (Hallway), Adição (Addition)',ARRAY['Found Floorplan']::text[],'Found Floorplans','https://gppfzdlqauygzvpodbdh.supabase.co/storage/v1/object/public/salas/Found%20Floorplans/Tunnel.png','https://blueprince.wiki.gg/wiki/Tunnel',now()),
('Conservatory',100,'Conservatory','Conservatory','This baroque arboretum showcases and preserves the rarest specimens of every type and variety. Through selective propagation, the gardener here may influence which flora (or floora) will be considered commonplace during the next season.','Este arboreto barroco exibe e preserva os espécimes mais raros de todo tipo e variedade. Por meio de propagação seletiva, o jardineiro daqui pode influenciar qual flora (ou "floora") será considerada comum na próxima estação.','Unusual','Incomum','1 gem','1 gema','Drafting, Green Room, Addition','Sorteio (Drafting), Sala Verde (Green Room), Adição (Addition)',ARRAY['Found Floorplan']::text[],'Found Floorplans','https://gppfzdlqauygzvpodbdh.supabase.co/storage/v1/object/public/salas/Found%20Floorplans/Conservatory.png','https://blueprince.wiki.gg/wiki/Conservatory',now()),
('Lost & Found',101,'Lost & Found','Lost & Found','There has always been a history of things disappearing on the estate, including this very floorplan, which had been lost for many years itself and missing from the directory. Now that it has been found, some long lost items from Mount Holly''s past might finally resurface...','Sempre houve um histórico de coisas desaparecendo na propriedade, incluindo esta própria planta, que ficou perdida por muitos anos e ausente do diretório. Agora que foi encontrada, alguns itens há muito perdidos do passado de Mount Holly podem finalmente ressurgir...','Unusual','Incomum','None (no gem cost)','Nenhum (sem custo em gemas)','Entry, Red Room, Addition','Entrada (Entry), Sala Vermelha (Red Room), Adição (Addition)',ARRAY['Found Floorplan']::text[],'Found Floorplans','https://gppfzdlqauygzvpodbdh.supabase.co/storage/v1/object/public/salas/Found%20Floorplans/Lost%20%26%20Found.png','https://blueprince.wiki.gg/wiki/Lost_&_Found',now()),
('Closed Exhibit',102,'Closed Exhibit','Closed Exhibit','A painstakingly produced accurate reproduction of one of the so-called "Closed" Exhibits of the Fenn Aries Royal Museum.','Uma reprodução meticulosamente fiel de uma das chamadas exposições "Fechadas" do Museu Real de Fenn Aries.','Rare','Raro','None (no gem cost)','Nenhum (sem custo em gemas)','Red Room, Addition','Sala Vermelha (Red Room), Adição (Addition)',ARRAY['Found Floorplan']::text[],'Found Floorplans','https://gppfzdlqauygzvpodbdh.supabase.co/storage/v1/object/public/salas/Found%20Floorplans/Closed%20Exhibit.png','https://blueprince.wiki.gg/wiki/Closed_Exhibit',now()),
('Toolshed',103,'Toolshed','Toolshed','A simple shed with a variety of tools used by the groundskeepers in the course of their duties.','Um galpão simples com uma variedade de ferramentas usadas pelos jardineiros no cumprimento de suas tarefas.','Unusual','Incomum','None (no gem cost)','Nenhum (sem custo em gemas)','Blueprint, Dead End, Outer Room','Blueprint (planta azul), Beco sem saída (Dead End), Outer Room',ARRAY['Outer Room']::text[],'Outer Rooms','https://gppfzdlqauygzvpodbdh.supabase.co/storage/v1/object/public/salas/Outer%20Rooms/Toolshed.png','https://blueprince.wiki.gg/wiki/Toolshed',now()),
('Shelter',104,'Shelter','Shelter','An underground bunker located away from the main house. This fallout shelter was designed specifically for air raids and features thick walls made from lead and other materials intended to block radiation. A computer terminal within has been connected to the house''s network system should an emergency necessitate remote access.','Um bunker subterrâneo localizado longe da casa principal. Este abrigo antinuclear foi projetado especificamente para ataques aéreos e possui paredes espessas feitas de chumbo e outros materiais destinados a bloquear a radiação. Um terminal de computador em seu interior foi conectado ao sistema de rede da casa, caso uma emergência exija acesso remoto.','Unusual','Incomum','None (no gem cost)','Nenhum (sem custo em gemas)','Blueprint, Dead End, Outer Room','Blueprint (planta azul), Beco sem saída (Dead End), Outer Room',ARRAY['Outer Room']::text[],'Outer Rooms','https://gppfzdlqauygzvpodbdh.supabase.co/storage/v1/object/public/salas/Outer%20Rooms/Shelter.png','https://blueprince.wiki.gg/wiki/Shelter',now()),
('Schoolhouse',105,'Schoolhouse','Schoolhouse','Long before Reddington Elementary was opened, school convened in a single small building. As the student body grew over the years, the need for separate classrooms for each grade arose and the Mt. Holly Schoolhouse was officially closed down.','Muito antes de a Escola Primária de Reddington ser inaugurada, as aulas eram dadas em um único prédio pequeno. Conforme o corpo discente crescia ao longo dos anos, surgiu a necessidade de salas separadas para cada série, e a Escolinha de Mt. Holly foi oficialmente fechada.','Unusual','Incomum','None (no gem cost)','Nenhum (sem custo em gemas)','Drafting, Blueprint, Dead End, Outer Room','Sorteio (Drafting), Blueprint (planta azul), Beco sem saída (Dead End), Outer Room',ARRAY['Outer Room']::text[],'Outer Rooms','https://gppfzdlqauygzvpodbdh.supabase.co/storage/v1/object/public/salas/Outer%20Rooms/Schoolhouse.png','https://blueprince.wiki.gg/wiki/Schoolhouse',now()),
('Shrine',106,'Shrine','Shrine','A sacred silence permeates this candlelit cavern, whose flickering lights add to the holy aura shining down upon a meditative statue. His stone hands present forth a stone bowl to the devout pilgrim who may wish to make an offering of gold.','Um silêncio sagrado permeia esta caverna iluminada por velas, cujas luzes bruxuleantes acentuam a aura sacra que reluz sobre uma estátua em meditação. Suas mãos de pedra estendem uma tigela de pedra ao devoto peregrino que deseje fazer uma oferenda de ouro.','Unusual','Incomum','None (no gem cost)','Nenhum (sem custo em gemas)','Blueprint, Dead End, Outer Room','Blueprint (planta azul), Beco sem saída (Dead End), Outer Room',ARRAY['Outer Room']::text[],'Outer Rooms','https://gppfzdlqauygzvpodbdh.supabase.co/storage/v1/object/public/salas/Outer%20Rooms/Shrine.png','https://blueprince.wiki.gg/wiki/Shrine',now()),
('Root Cellar',107,'Root Cellar','Root Cellar','An underground store of jarred vegetables and fruits from Mount Holly''s gardens. It''s always amazing what great things come from a little digging around in the dirt.','Um depósito subterrâneo de legumes e frutas em conserva dos jardins de Mount Holly. É sempre incrível as grandes coisas que surgem de um pouco de escavação na terra.','Unusual','Incomum','None (no gem cost)','Nenhum (sem custo em gemas)','Green Room, Dead End, Outer Room','Sala Verde (Green Room), Beco sem saída (Dead End), Outer Room',ARRAY['Outer Room']::text[],'Outer Rooms','https://gppfzdlqauygzvpodbdh.supabase.co/storage/v1/object/public/salas/Outer%20Rooms/Root%20Cellar.png','https://blueprince.wiki.gg/wiki/Root_Cellar',now()),
('Hovel',108,'Hovel','Hovel','A squalid dwelling on the edge of the estate belonging to one of the groundskeepers.','Uma moradia miserável na borda da propriedade, pertencente a um dos jardineiros.','Unusual','Incomum','None (no gem cost)','Nenhum (sem custo em gemas)','Bedroom, Dead End, Outer Room','Quarto (Bedroom), Beco sem saída (Dead End), Outer Room',ARRAY['Outer Room']::text[],'Outer Rooms','https://gppfzdlqauygzvpodbdh.supabase.co/storage/v1/object/public/salas/Outer%20Rooms/Hovel.png','https://blueprince.wiki.gg/wiki/Hovel',now()),
('Trading Post',109,'Trading Post','Trading Post','An outpost established on the outskirts of Mount Holly in the era before the new realms. This station allowed the frontiersman and trappers of these mountains to trade goods and services with the estate, the locals and one another.','Um entreposto estabelecido nos arredores de Mount Holly na era anterior aos novos reinos. Este posto permitia que os desbravadores e caçadores destas montanhas trocassem bens e serviços com a propriedade, com os moradores locais e entre si.','Unusual','Incomum','None (no gem cost)','Nenhum (sem custo em gemas)','Shop, Dead End, Outer Room','Loja (Shop), Beco sem saída (Dead End), Outer Room',ARRAY['Outer Room']::text[],'Outer Rooms','https://gppfzdlqauygzvpodbdh.supabase.co/storage/v1/object/public/salas/Outer%20Rooms/Trading%20Post.png','https://blueprince.wiki.gg/wiki/Trading_Post',now()),
('Tomb',110,'Tomb','Tomb','This Sinclair family crypt is as gloomy as it is immense. The true Sinclair legacy lies here, resting underneath the stones, a parade of distant relations and forgotten ancestors.','Esta cripta da família Sinclair é tão sombria quanto imensa. O verdadeiro legado dos Sinclair repousa aqui, sob as pedras, um desfile de parentes distantes e ancestrais esquecidos.','Unusual','Incomum','None (no gem cost)','Nenhum (sem custo em gemas)','Blackprint, Dead End, Outer Room','Blackprint (planta negra), Beco sem saída (Dead End), Outer Room',ARRAY['Outer Room']::text[],'Outer Rooms','https://gppfzdlqauygzvpodbdh.supabase.co/storage/v1/object/public/salas/Outer%20Rooms/Tomb.png','https://blueprince.wiki.gg/wiki/Tomb',now()) on conflict (nome) do update set num=excluded.num,nome_en=excluded.nome_en,nome_pt=excluded.nome_pt,descricao_en=excluded.descricao_en,descricao_pt=excluded.descricao_pt,raridade_en=excluded.raridade_en,raridade_pt=excluded.raridade_pt,custo_en=excluded.custo_en,custo_pt=excluded.custo_pt,tipo_en=excluded.tipo_en,tipo_pt=excluded.tipo_pt,categorias=excluded.categorias,diretorio=excluded.diretorio,imagem=excluded.imagem,fonte=excluded.fonte,atualizado_em=excluded.atualizado_em;
